/**
 * Offline, comprehensive symbol directory - the single source of truth for
 * "every real listed ticker is findable" across the whole app (TickerScope, the
 * ⌘K command bar, watchlist add, Blueprint, detail). Backed by a bundled static
 * asset (`listings.generated.ts`, regenerated by scripts/gen-symbol-directory.mjs)
 * so search/resolve never depends on a live API call succeeding.
 *
 * US: NASDAQ Trader (NASDAQ/NYSE/Arca/AMEX/Cboe/IEX). CA: TSX/TSXV/Cboe Canada.
 * Pure + synchronous + dependency-free.
 */

import { SYMBOL_ROWS, SYMBOL_COUNTS, type CompactRow } from "./listings.generated";

export interface SymbolRecord {
  symbol: string;
  name: string;
  exchange: string;
  country: "US" | "CA";
  isEtf: boolean;
}

function toRecord(r: CompactRow): SymbolRecord {
  return { symbol: r.s, name: r.n, exchange: r.x, country: r.c, isEtf: r.e === 1 };
}

const RECORDS: SymbolRecord[] = SYMBOL_ROWS.map(toRecord);
const BY_SYMBOL = new Map<string, SymbolRecord>();
for (const rec of RECORDS) BY_SYMBOL.set(rec.symbol, rec);

const SUFFIXES = [".TO", ".V", ".NE"] as const;

function norm(q: string): string {
  return q.trim().toUpperCase();
}

/**
 * Exact-symbol lookup, case-insensitive, suffix-tolerant: "MDA.TO" matches
 * directly; a bare "MDA" will also find "MDA.TO" when no plain "MDA" exists; and
 * a suffixed query falls back to its base ticker. Never strips a suffix the user
 * typed if the exact form exists.
 */
export function getSymbol(symbol: string): SymbolRecord | null {
  const key = norm(symbol);
  if (!key) return null;
  const direct = BY_SYMBOL.get(key);
  if (direct) return direct;
  if (key.includes(".")) {
    const base = key.split(".")[0]!;
    return BY_SYMBOL.get(base) ?? null;
  }
  for (const suffix of SUFFIXES) {
    const hit = BY_SYMBOL.get(key + suffix);
    if (hit) return hit;
  }
  return null;
}

function scoreRow(qUpper: string, qLower: string, rec: SymbolRecord): number {
  const sym = rec.symbol;
  const base = sym.split(".")[0]!;
  const nameLower = rec.name.toLowerCase();

  let rel = 0;
  if (sym === qUpper || base === qUpper) rel = 1000;
  else if (sym.startsWith(qUpper) || base.startsWith(qUpper)) rel = 600;
  else if (nameLower === qLower) rel = 400;
  else if (nameLower.startsWith(qLower)) rel = 300;
  else if (nameLower.includes(qLower)) rel = 120;
  else return 0;

  // Tiebreakers - only applied once the row is genuinely relevant.
  if (rec.country === "US") rel += 20; // US-biased ranking (most lookups)
  if (!rec.isEtf) rel += 15; // prefer the common stock over a same-name ETF
  rel += Math.max(0, 8 - base.length); // cleaner/shorter tickers first
  return rel;
}

/** Ranked prefix/substring search over the whole directory (for autocomplete). */
export function searchSymbols(query: string, limit = 20): SymbolRecord[] {
  const qUpper = norm(query);
  if (!qUpper) return [];
  const qLower = query.trim().toLowerCase();
  const scored: Array<{ rec: SymbolRecord; score: number }> = [];
  for (const rec of RECORDS) {
    const score = scoreRow(qUpper, qLower, rec);
    if (score > 0) scored.push({ rec, score });
  }
  scored.sort((a, b) => b.score - a.score || (a.rec.symbol < b.rec.symbol ? -1 : 1));
  return scored.slice(0, limit).map((x) => x.rec);
}

/** Best single match for a ticker-or-name query - exact symbol first, else top search hit. */
export function resolveSymbol(query: string): SymbolRecord | null {
  const direct = getSymbol(query);
  if (direct) return direct;
  return searchSymbols(query, 1)[0] ?? null;
}

/** True when a query maps to a real listed security in the bundled directory. */
export function isKnownSymbol(query: string): boolean {
  return resolveSymbol(query) != null;
}

export function directoryStats(): { total: number; us: number; ca: number } {
  return { total: SYMBOL_COUNTS.total, us: SYMBOL_COUNTS.us, ca: SYMBOL_COUNTS.ca };
}

/**
 * Every listed record in the bundled directory. Read-only - the array is the
 * directory's internal store, so callers must not mutate it. Used by the
 * dual-listing resolver to find a company's other exchange listings.
 */
export function allSymbolRecords(): readonly SymbolRecord[] {
  return RECORDS;
}
